/* Explanatory inference flow only. No classifier execution or photo transmission. */
(function(root){
 'use strict';
 const steps=[
  {title:'Rice-leaf photo',tag:'USER INPUT',short:'JPEG · PNG · WebP',detail:'Choose a clear rice-leaf photo. The current app previews it locally. Selecting a file does not run a classifier or upload the photo.'},
  {title:'File checks',tag:'VALIDATION',short:'Format · size · resolution',detail:'Check the file signature and decode the image. Accept JPEG, PNG or WebP up to 10 MB, at least 128 × 128 pixels and no more than 24 megapixels. Invalid files return an error; the user selects another photo. These checks do not verify that the photo contains rice.'},
  {title:'Image preprocessing',tag:'MODEL INPUT',short:'RGB → 3 × 224 × 224',detail:'Proposed inference reuses the evaluation transforms: correct orientation, convert to RGB, resize the shorter edge to 256 pixels, centre-crop to 224 × 224 and normalize channels using ImageNet mean [0.485, 0.456, 0.406] and standard deviation [0.229, 0.224, 0.225]. Random augmentation is for training only.'},
  {title:'EfficientNet-B0',tag:'IMAGE MODEL',short:'Learned visual features',detail:'ImageNet-pretrained EfficientNet-B0 extracts visual features. Fine-tuning will adapt the classification head and final two backbone blocks to our rice photos. The backbone is downloaded; the four-class rice classifier has not been trained or connected to the app.'},
  {title:'Four class scores',tag:'CLASSIFICATION',short:'Softmax → ranked classes',detail:'After training, four output logits can be converted with softmax: pᵢ = exp(zᵢ) / Σ exp(zⱼ). The highest score supplies a candidate label. A softmax score is not a guarantee of correctness and does not reliably reject other crops or unsupported diseases.'},
  {title:'Result and guidance',tag:'USER OUTPUT',short:'Class label + explanation',detail:'The proposed result shows a candidate rice-health label and class-score breakdown. District, season and growth stage may accompany general reference guidance, separately from classification. The image result does not calculate yield loss. Today the app returns no diagnosis because no trained classifier is connected.'}
 ];
 function markup(){return `<section id="detection-section" class="detection-diagram" aria-labelledby="detection-title">
  <div class="detection-heading"><div><p class="eyebrow">PHOTO TO RESULT</p><h2 id="detection-title">Rice disease detection flow</h2><p>Proposed inference after training. Select a step to inspect it.</p></div><span class="small-badge">CLASSIFIER NOT CONNECTED</span></div>
  <ol class="detection-track" aria-label="Image classification steps">${steps.map((s,i)=>`<li><button type="button" class="detection-node${i===0?' is-selected':''}" data-detection-step="${i}" aria-pressed="${i===0}" aria-controls="detection-detail"><span class="detection-number">0${i+1}</span><span class="detection-tag">${s.tag}</span><strong>${s.title}</strong><span class="detection-short">${s.short}</span></button></li>`).join('')}</ol>
  <div class="detection-exits"><span><b>Invalid file</b> → Show error → Select another photo</span><span><b>Current prototype</b> → Local preview only · No disease prediction</span></div>
  <div id="detection-detail" class="detection-detail" role="status" aria-live="polite" aria-atomic="true"><span class="eyebrow">STEP 01</span><h3>${steps[0].title}</h3><p>${steps[0].detail}</p></div>
  <div class="detection-context"><div><span class="eyebrow">SEPARATE CONTEXT BRANCH</span><p>District + season + growth stage <span aria-hidden="true">→</span> Reference guidance <span aria-hidden="true">→</span> Display beside the image result</p></div><p>Context does not change the class scores or predicted yield.</p></div>
  <div class="detection-classes"><span>Supported labels</span><b>Bacterial leaf blight</b><b>Blast</b><b>Brown spot</b><b>Healthy / normal</b></div>
  <div class="detection-influence"><h3>What influences the detection?</h3><p>The classifier receives image pixels, not rainfall, district or season. Learned visual features may use lesion colour, shape, texture and surrounding leaf patterns. Their actual importance is not measured yet.</p><div class="detection-influence-state"><b>Image-region importance: pending training</b><span>A model-based heatmap can be added after training to show influential image regions. It would indicate model attention, not prove a correct diagnosis.</span></div><p>Weather and location are advisory context only. No disease-related yield loss or feature-importance percentages are inferred.</p></div>
  <p class="detection-note">Prepared: 1,600 rice photos · 1,120 training / 240 validation / 240 test. This is image classification, not lesion segmentation. Other crops and diseases are outside the trained scope; rejection of unsupported inputs still needs validation.</p>
 </section>`;}
 function influenceMarkup(request){
  const y=Number(request.illustrativeYieldTPerHa),a=Number(request.areaHa);
  if(!Number.isFinite(y)||y<0||!Number.isFinite(a)||a<=0)throw new Error('Invalid output-driver inputs');
  const n=value=>value.toLocaleString('en-IN',{maximumFractionDigits:2});
  return `<section class="output-influence" aria-label="Inputs influencing this output"><div class="detection-heading"><div><p class="eyebrow">OUTPUT DRIVERS</p><h3>Which inputs affect this result?</h3></div><span class="small-badge">ARITHMETIC · NOT FEATURE IMPORTANCE</span></div><p>Current production = demo yield × cultivation area. Both have equal proportional influence when the other is fixed; neither is ranked by a trained model.</p><div class="influence-grid"><article><span>Demo yield assumption</span><strong>${n(y)} t/ha</strong><p>Increase yield by 10%, keeping area fixed:<br><b>+${n(y*a*.1)} tonnes</b></p></article><article><span>Cultivation area</span><strong>${n(a)} ha</strong><p>Increase area by 10%, keeping yield fixed:<br><b>+${n(y*a*.1)} tonnes</b></p></article></div><p class="influence-pending"><b>Weather / location importance: not available yet.</b> Rainfall, temperature, radiation and other features are inputs to future yield models, but do not affect this manual demo yield. Their ranking must be measured after training; district/season only select context and historical references here. Sale price changes gross value, not yield or tonnes.</p><details><summary>How trained-model influence will be explained</summary><p>For yield models, validation-set permutation importance can rank features by how much prediction error increases when each input is shuffled. That is a global ranking, not an explanation of one specific prediction. Per-result contributions require a separate local explanation method. DAE latent features are not directly equivalent to named weather measurements. For the image model, an image-region heatmap can show influential pixels; it is not a weather-feature ranking.</p></details></section>`;
 }
 root.DetectionFlow={steps,markup,influenceMarkup};
 if(typeof module!=='undefined'&&module.exports)module.exports=root.DetectionFlow;
 if(typeof document==='undefined')return;
 root.DetectionFlow.mount=function(anchor){
 anchor.insertAdjacentHTML('beforeend',markup());
 const section=document.getElementById('detection-section'),buttons=[...section.querySelectorAll('[data-detection-step]')],detail=section.querySelector('#detection-detail');
 function select(index){buttons.forEach((button,i)=>{button.classList.toggle('is-selected',i===index);button.setAttribute('aria-pressed',String(i===index));});const step=steps[index];detail.querySelector('.eyebrow').textContent=`STEP ${String(index+1).padStart(2,'0')}`;detail.querySelector('h3').textContent=step.title;detail.querySelector('p').textContent=step.detail;}
 buttons.forEach((button,index)=>{button.addEventListener('click',()=>select(index));button.addEventListener('keydown',event=>{const offsets={ArrowRight:1,ArrowDown:1,ArrowLeft:-1,ArrowUp:-1};let next;if(event.key==='Home')next=0;else if(event.key==='End')next=buttons.length-1;else if(event.key in offsets)next=(index+offsets[event.key]+buttons.length)%buttons.length;else return;event.preventDefault();select(next);buttons[next].focus();});});
 };
})(typeof window!=='undefined'?window:globalThis);
